-- Synthetic fixture; no provider calls. Same foundation prefix used by other suites.
update public.organizations set status='active' where id='20000000-0000-4000-8000-000000000001';
insert into public.entitlements values('20000000-0000-4000-8000-000000000001','scheduling',true);
insert into private.schedule_state values('20000000-0000-4000-8000-000000000001',1);
insert into public.configuration_versions(organization_id,version,settings) values('20000000-0000-4000-8000-000000000001',2,'{"displayName":"Synthetic Company","timezone":"America/Chicago","notificationRecipient":"owner@example.invalid","sender":"owner@example.invalid"}');
insert into public.resources(organization_id,id,name,kind) values('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','Synthetic operator','operator');
insert into public.service_requests(organization_id,id,service_id,status,original_submission,privacy_version) select '20000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001',id,'reviewing','{"name":"Synthetic Customer","email":"customer@example.invalid","street":"100 Test Street","city":"Test","services":[{"service":"Yard","task":"Mulch"},{"service":"Home","task":"Door adjustment"}]}','test-only' from public.catalog_services;
insert into public.appointments(organization_id,id,request_id,start_at,end_at,arrival_at,timezone,status,revision) values('20000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001',now()+interval '10 days',now()+interval '10 days 2 hours',now()+interval '10 days 30 minutes','America/Chicago','reserved',3);
insert into public.resource_reservations(organization_id,appointment_id,resource_id,during,active) select organization_id,id,'40000000-0000-4000-8000-000000000001',tstzrange(start_at,end_at,'[)'),true from public.appointments;
insert into public.outbox(organization_id,id,kind,event_key,object_id,payload,status,lease_token,lease_until) values('20000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001','appointment.confirmation','synthetic-confirmation','60000000-0000-4000-8000-000000000001','{"appointmentRevision":3}','leased','80000000-0000-4000-8000-000000000001',now()+interval '5 minutes');
update public.organizations set status='active' where id='20000000-0000-4000-8000-000000000001';
insert into private.google_accounts(organization_id,revision,encrypted_tokens,email,subject,scopes,gmail_test,test_key) values('20000000-0000-4000-8000-000000000001',1,'synthetic-not-real','owner@example.invalid','synthetic-subject',array['https://www.googleapis.com/auth/gmail.send'],'accepted','90000000-0000-4000-8000-000000000001');
insert into private.mail_delivery_controls(organization_id,enabled,account_subject,test_key,configuration_version,receipt_confirmed_at,receipt_confirmed_by) values('20000000-0000-4000-8000-000000000001',true,'synthetic-subject','90000000-0000-4000-8000-000000000001',2,now(),'00000000-0000-4000-8000-000000000001');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select public.issue_customer_request_link('20000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001',repeat('a',64));
select public.issue_customer_request_link('20000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001',repeat('a',64));
select pg_temp.assert_true(not has_function_privilege('anon','public.customer_request_action(text,jsonb,text)','EXECUTE'),'anonymous cannot call action bridge');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.customer_request_context(text)','EXECUTE'),'ordinary client cannot read request bearer context directly');
select pg_temp.assert_true(not has_table_privilege('authenticated','private.customer_request_links','SELECT'),'hashed link table remains private');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002","aal":"aal2"}',true);
do $$begin begin perform public.issue_customer_request_link('20000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001',repeat('b',64));raise exception 'TEST FAILED other owner issued link';exception when insufficient_privilege then null;end;end$$;
reset role;
select pg_temp.assert_true((select count(*)=1 from private.customer_request_links),'issuer retry creates one grant');
select pg_temp.assert_true((select expires_at<=now()+interval '7 days 1 second' from private.customer_request_links),'link lifetime bounded');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert_true(public.customer_request_context(repeat('a',64))->>'company'='Synthetic Company','context uses current company');
select pg_temp.assert_true(jsonb_array_length(public.customer_request_context(repeat('a',64))->'services')=2,'same-request context keeps categories');
select pg_temp.assert_true(not (public.customer_request_context(repeat('a',64)) ? 'invoices'),'link excludes household invoice history');
do $$begin begin perform public.customer_request_context(repeat('b',64));raise exception 'TEST FAILED unknown token';exception when raise_exception then if sqlerrm<>'LINK_UNAVAILABLE' then raise;end if;end;end$$;
select public.customer_request_action(repeat('a',64),'{"action":"confirm","appointmentRevision":3,"responseVersion":0,"configurationVersion":2,"preferredLocalStart":null,"note":""}','customer-confirm-0001');
select public.customer_request_action(repeat('a',64),'{"action":"confirm","appointmentRevision":3,"responseVersion":0,"configurationVersion":2,"preferredLocalStart":null,"note":""}','customer-confirm-0001');
do $$begin begin perform public.customer_request_action(repeat('a',64),'{"action":"confirm","appointmentRevision":3,"responseVersion":0,"configurationVersion":2,"preferredLocalStart":null,"note":""}','customer-confirm-0002');raise exception 'TEST FAILED stale response';exception when raise_exception then if sqlerrm<>'STALE_REVISION' then raise;end if;end;end$$;
do $$begin begin perform public.customer_request_action(repeat('a',64),'{"action":"confirm","appointmentRevision":3,"responseVersion":1,"configurationVersion":2,"preferredLocalStart":null,"note":""}','customer-confirm-0001');raise exception 'TEST FAILED changed retry';exception when raise_exception then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;end$$;
select public.customer_request_action(repeat('a',64),'{"action":"request_another_time","appointmentRevision":3,"responseVersion":1,"configurationVersion":2,"preferredLocalStart":"2026-10-20T09:00","note":"Tuesday morning would work for us."}','customer-reschedule-01');
select public.customer_request_action(repeat('a',64),'{"action":"request_another_time","appointmentRevision":3,"responseVersion":1,"configurationVersion":2,"preferredLocalStart":"2026-10-20T09:00","note":"Tuesday morning would work for us."}','customer-reschedule-01');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.appointments where status='reserved' and revision=3 and response_version=2 and customer_response='reschedule_requested'),'response retains original appointment and capacity revision');
select pg_temp.assert_true((select count(*)=1 from public.resource_reservations where active),'response does not release original resource');
select pg_temp.assert_true((select count(*)=1 from public.customer_schedule_preferences where status='pending'),'one durable preferred-time record after retry');
select pg_temp.assert_true((select count(*)=1 from public.outbox where kind='appointment.reschedule_requested'),'one owner reschedule notice after retry');
select pg_temp.assert_true((select count(*)=0 from public.jobs),'customer response creates no duplicate job');
select pg_temp.assert_true((select count(*)=0 from public.invoices),'customer response cannot issue an invoice');
-- Expiry and changed recipient fail independently of appointment state.
update private.customer_request_links set created_at=clock_timestamp()-interval '2 hours',expires_at=clock_timestamp()-interval '1 hour';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
do $$begin begin perform public.customer_request_context(repeat('a',64));raise exception 'TEST FAILED expired link';exception when raise_exception then if sqlerrm<>'LINK_UNAVAILABLE' then raise;end if;end;end$$;
reset role;
update private.customer_request_links set expires_at=clock_timestamp()+interval '2 hours',recipient_hash=repeat('b',64);
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
do $$begin begin perform public.customer_request_context(repeat('a',64));raise exception 'TEST FAILED changed recipient';exception when raise_exception then if sqlerrm<>'LINK_UNAVAILABLE' then raise;end if;end;end$$;
reset role;
update private.customer_request_links set recipient_hash=encode(sha256(convert_to('customer@example.invalid','UTF8')),'hex');
-- A declined-time link returns to this request and cannot attendance-confirm an unbooked proposal.
insert into public.appointments(organization_id,id,request_id,start_at,end_at,arrival_at,timezone,status,revision) values('20000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000001',now()+interval '11 days',now()+interval '11 days 2 hours',now()+interval '11 days','America/Chicago','declined_time',2);
update public.appointments set replaces_id='60000000-0000-4000-8000-000000000001' where id='60000000-0000-4000-8000-000000000002';
insert into public.outbox(organization_id,id,kind,event_key,object_id,payload,status,lease_token,lease_until) values('20000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000002','appointment.declined_time','synthetic-declined-time','60000000-0000-4000-8000-000000000002','{"appointmentRevision":2,"reason":"That time is unavailable."}','leased','80000000-0000-4000-8000-000000000002',now()+interval '5 minutes');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select public.issue_customer_request_link('20000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000002','80000000-0000-4000-8000-000000000002',repeat('c',64));
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert_true(public.customer_request_context(repeat('c',64))->'actions'='["request_another_time"]'::jsonb,'declined-time link offers another time without confirming');
do $$begin begin perform public.customer_request_action(repeat('c',64),'{"action":"confirm","appointmentRevision":2,"responseVersion":0,"configurationVersion":2,"preferredLocalStart":null,"note":""}','customer-invalid-confirm');raise exception 'TEST FAILED confirm declined';exception when raise_exception then if sqlerrm<>'TRANSITION' then raise;end if;end;end$$;
select public.customer_request_action(repeat('c',64),'{"action":"request_another_time","appointmentRevision":2,"responseVersion":0,"configurationVersion":2,"preferredLocalStart":null,"note":"Thursday morning would be better."}','customer-declined-retry');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.service_requests),'declined-time action retains the original request');
-- A new alternative supersedes actions from an older declined alternative.
insert into public.appointments(organization_id,id,request_id,start_at,end_at,arrival_at,timezone,status,revision,replaces_id,expires_at) values('20000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000003','50000000-0000-4000-8000-000000000001',now()+interval '12 days',now()+interval '12 days 2 hours',now()+interval '12 days','America/Chicago','proposal',2,'60000000-0000-4000-8000-000000000001',now()+interval '2 hours');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
do $$begin begin perform public.customer_request_context(repeat('c',64));raise exception 'TEST FAILED superseded declined link';exception when raise_exception then if sqlerrm<>'LINK_UNAVAILABLE' then raise;end if;end;end$$;
reset role;
-- Modified/canceled appointment revokes links and pending preferences.
update public.appointments set status='canceled',revision=revision+1;
select pg_temp.assert_true((select count(*)=2 from private.customer_request_links where revoked_at is not null),'cancellation invalidates old links');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
do $$begin begin perform public.customer_request_context(repeat('a',64));raise exception 'TEST FAILED canceled link';exception when raise_exception then if sqlerrm<>'LINK_UNAVAILABLE' then raise;end if;end;end$$;
reset role;
rollback;
